using System;
class SenseChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var e=new SenseEffects();e.Blur(0);e.GreaterInvisible(false,0);Check(e.Blurred(9)&&e.Invisible(false,9)&&!e.Invisible(true,9),"concentration target and minute duration");Check(!e.Blurred(10)&&!e.Invisible(false,10),"minute expiry");e.SeeInvisible(0);e.TrueSeeing(true,0);Check(e.RevealsInvisible(true,150,0,0),"see invisibility still works beyond truesight range");Check(!e.RevealsInvisible(false,10,0,0),"see invisibility is self only");e.TrueSeeing(false,0);Check(e.RevealsInvisible(false,120.2,0,0)&&!e.RevealsInvisible(false,120.6,0,0),"truesight range and recipient");Check(e.RevealsInvisible(false,10,0,10)&&!e.RevealsInvisible(false,11,600,10),"blindsight range");e.EndConcentration();Check(e.TrueSight(false,0)&&e.SeesInvisible(true,0)&&!e.Invisible(false,0),"concentration ends without ending nonconcentration senses");var v=new VisionState();v.AddZone(true,20,0,4,0);Check(v.Quality(0,0,40,0,0,0,0,true)==0&&v.Quality(0,0,40,0,150,0)==2,"truesight pierces magical darkness but darkvision does not");v.AddFog(20,0,1,0);Check(v.Quality(0,0,40,0,0,0,0,true)==2,"physical fog still blocks truesight");Check(v.Quality(0,0,10,0,0,0,10,true)==0,"blindsight can perceive through physical fog");e.Clear();Check(!e.TrueSight(false,0)&&!e.SeesInvisible(true,0),"reset");Console.WriteLine("PASS: blur and invisibility duration, concentration, independent senses, range boundaries, darkness, fog and reset");}
}
